DO $repair$ DECLARE body text;BEGIN SELECT pg_get_functiondef('public.pipeline_candidate_action(text,text,jsonb)'::regprocedure) INTO body;body:=replace(body,'answer !~ ''^[1-5],[1-5],[1-5],[1-5]$''','answer !~ ''^[1-5]?,[1-5]?,[1-5]?,[1-5]?$''');EXECUTE body;SELECT pg_get_functiondef('public.pipeline_accommodation(uuid,integer,text,text)'::regprocedure) INTO body;body:=replace(body,'BEGIN SELECT * INTO a FROM assessment_attempts WHERE id=aid;','BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT * INTO a FROM assessment_attempts WHERE id=aid FOR UPDATE;');EXECUTE body;END $repair$;